import * as THREE from 'three';
export function makeHalo(size=2.2){const c=document.createElement('canvas');c.width=c.height=2048;const x=c.getContext('2d');x.translate(1024,1024);x.font='96px "Lora-SemiBold"';x.fillStyle='#FFD9A8';x.textAlign='center';x.textBaseline='middle';const chars=[...'OPUS 5.5 · OPUS 5.5 · OPUS 5.5 · '];for(let i=0;i<chars.length;i++){x.save();x.rotate(i/chars.length*Math.PI*2);x.fillText(chars[i],0,-850);x.restore();}let tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;tex.anisotropy=8;let m=new THREE.Mesh(new THREE.PlaneGeometry(size,size),new THREE.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false,side:THREE.DoubleSide,toneMapped:false}));m.rotation.x=-Math.PI/2;return m;}
