export async function loadVector(url){const s=await(await fetch(url)).text();const dom=new DOMParser().parseFromString(s,'image/svg+xml');if(dom.querySelector('parsererror'))throw Error('bad SVG '+url);const vb=dom.documentElement.getAttribute('viewBox').split(/[ ,]+/).map(Number);return{raw:s,vb,paths:[...dom.querySelectorAll('path')].map(p=>({p:new Path2D(p.getAttribute('d')),fill:p.getAttribute('fill')||'#D97757'}))};}
export function vector(ctx,v,cx,cy,size,angle=0,override){ctx.save();ctx.translate(cx,cy);ctx.rotate(angle);const sc=size/v.vb[2];ctx.scale(sc,sc);ctx.translate(-v.vb[2]/2,-v.vb[3]/2);for(const p of v.paths){ctx.fillStyle=override||p.fill;ctx.fill(p.p);}ctx.restore();}
