// Perspective image warp in Canvas2D, tessellated into affine triangles.
function tri(ctx,img,src,dst){let [a,b,c]=src,[A,B,C]=dst;let den=a[0]*(b[1]-c[1])+b[0]*(c[1]-a[1])+c[0]*(a[1]-b[1]);if(Math.abs(den)<1e-9)return;let solve=vals=>[(vals[0]*(b[1]-c[1])+vals[1]*(c[1]-a[1])+vals[2]*(a[1]-b[1]))/den,(vals[0]*(c[0]-b[0])+vals[1]*(a[0]-c[0])+vals[2]*(b[0]-a[0]))/den,(vals[0]*(b[0]*c[1]-c[0]*b[1])+vals[1]*(c[0]*a[1]-a[0]*c[1])+vals[2]*(a[0]*b[1]-b[0]*a[1]))/den];let X=solve([A[0],B[0],C[0]]),Y=solve([A[1],B[1],C[1]]);ctx.save();ctx.beginPath();ctx.moveTo(...A);ctx.lineTo(...B);ctx.lineTo(...C);ctx.closePath();ctx.clip();ctx.transform(X[0],Y[0],X[1],Y[1],X[2],Y[2]);ctx.drawImage(img,0,0);ctx.restore();}
export function project(ctx,img,q,n=16){let p=(u,v)=>[q[0][0]*(1-u)*(1-v)+q[1][0]*u*(1-v)+q[2][0]*u*v+q[3][0]*(1-u)*v,q[0][1]*(1-u)*(1-v)+q[1][1]*u*(1-v)+q[2][1]*u*v+q[3][1]*(1-u)*v];for(let y=0;y<n;y++)for(let x=0;x<n;x++){let u=x/n,v=y/n,U=(x+1)/n,V=(y+1)/n;let s=[[u*img.width,v*img.height],[U*img.width,v*img.height],[U*img.width,V*img.height],[u*img.width,V*img.height]],d=[p(u,v),p(U,v),p(U,V),p(u,V)];tri(ctx,img,[s[0],s[1],s[2]],[d[0],d[1],d[2]]);tri(ctx,img,[s[0],s[2],s[3]],[d[0],d[2],d[3]]);}}
